syntax:
namespace_name::identifier
// or
class_name::member_name
// used to define or access members within a specific namespace or class scope

code_example:
#include <iostream>

namespace A {
    namespace N {
        int i = 10;
        class MyClass {
        public:
            void f();
        };
    }
}

void A::N::MyClass::f() {
    i = 5; // Error: 'i' is not directly accessible here
    A::N::i = 5; // Correct: explicitly specifying namespace scope
    std::cout << "i = " << A::N::i << std::endl;
}
